import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"支持曦寒","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/support.md","filePath":"appendix/support.md","lastUpdated":1794052435000}`),a={name:`appendix/support.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="支持曦寒" tabindex="-1">支持曦寒 <a class="header-anchor" href="#支持曦寒" aria-label="Permalink to “支持曦寒”">​</a></h1><p>XiHan Framework 与整个曦寒懿生态自发布以来一直采用 MIT 协议：核心能力永久免费，个人与企业都可以使用和商用，开源版本完整可用、不做削弱，已经以 MIT 公开的能力不会再改成收费。这一页说明你可以怎样支持这个项目，以及遇到问题时去哪里。</p><h2 id="一个-star" tabindex="-1">一个 Star <a class="header-anchor" href="#一个-star" aria-label="Permalink to “一个 Star”">​</a></h2><p>最简单的支持。仓库在三处托管，Issue 与 Pull Request 在哪一处提都收得到：</p><table tabindex="0"><thead><tr><th>平台</th><th>地址</th></tr></thead><tbody><tr><td>GitHub（主库）</td><td><a href="https://github.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHanFun/XiHan.Framework</a></td></tr><tr><td>Gitee（同步备库）</td><td><a href="https://gitee.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHanFun/XiHan.Framework</a></td></tr><tr><td>GitCode（同步备库）</td><td><a href="https://gitcode.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHanFun/XiHan.Framework</a></td></tr></tbody></table><h2 id="反馈问题" tabindex="-1">反馈问题 <a class="header-anchor" href="#反馈问题" aria-label="Permalink to “反馈问题”">​</a></h2><ul><li>缺陷与功能建议：<a href="https://github.com/XiHanFun/XiHan.Framework/issues" target="_blank" rel="noreferrer">GitHub Issues</a>。提缺陷时附上框架版本、复现步骤、启动日志里打印的能力图谱与管道，以及 Problem Details 里的错误码与 <code>traceId</code>。</li><li>规范问题（原语语义、清单 Schema、协议映射、插件协议）：提到 <a href="https://github.com/XiHanFun/framework-spec" target="_blank" rel="noreferrer">framework-spec</a>。</li><li>安全漏洞：不要公开提 Issue，发邮件到 <a href="mailto:me@xihanfun.com" target="_blank" rel="noreferrer">me@xihanfun.com</a>。</li><li>交流群：QQ 群 462371834。</li></ul><h2 id="参与贡献" tabindex="-1">参与贡献 <a class="header-anchor" href="#参与贡献" aria-label="Permalink to “参与贡献”">​</a></h2><p>贡献代码、文档、示例与一致性向量都欢迎。流程与规范见<a href="/appendix/contributing">贡献指南</a>，组织层面的公约见<a href="https://docs.xihanfun.com/cosmos/code-of-conduct" target="_blank" rel="noreferrer">贡献者公约</a>。</p><p>几类特别欢迎的贡献：</p><table tabindex="0"><thead><tr><th>方向</th><th>说明</th></tr></thead><tbody><tr><td>Provider</td><td>为某个子系统写一个新的实现并通过一致性套件，见<a href="/extending/provider">写一个 Provider</a></td></tr><tr><td>语言 SDK</td><td>按 XiHan Spec 实现另一种语言的原语、清单、上下文与插件运行时，见<a href="/appendix/spec">规范与多语言</a></td></tr><tr><td>文档</td><td>教程里讲不清的地方、示例跑不通的地方，直接改这一站的 Markdown</td></tr><tr><td>一致性向量</td><td>发现实现之间行为不一致时，把它写成向量提到规范仓库</td></tr></tbody></table><h2 id="赞助" tabindex="-1">赞助 <a class="header-anchor" href="#赞助" aria-label="Permalink to “赞助”">​</a></h2><p>开发框架、视图组件、基础应用、四款设计器和相关文档站都由作者和贡献者长期维护。赞助用于在线预览环境、云服务器、数据库与对象存储、域名与证书、AI 服务与第三方平台费用，以及文档和功能的持续迭代。</p><p>赞助方式、等级与赞助榜单见<a href="https://docs.xihanfun.com/cosmos/sponsor" target="_blank" rel="noreferrer">支持与赞助</a>。按月赞助的企业或团队会在全部文档站的赞助位展示；个人支持者会进入赞助榜单。赞助后请来信告知要展示的名称、留言和链接。</p><h2 id="生态里的其他项目" tabindex="-1">生态里的其他项目 <a class="header-anchor" href="#生态里的其他项目" aria-label="Permalink to “生态里的其他项目”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th><th>文档</th></tr></thead><tbody><tr><td>XiHan.UI</td><td>框架无关的 headless 视图组件库，生态的前端基座</td><td><a href="https://ui.docs.xihanfun.com" target="_blank" rel="noreferrer">ui.docs.xihanfun.com</a></td></tr><tr><td>XiHan.BasicApp</td><td>基于本框架与 XiHan.UI 的通用管理内核</td><td><a href="https://basicapp.docs.xihanfun.com" target="_blank" rel="noreferrer">basicapp.docs.xihanfun.com</a></td></tr><tr><td>打印、流程、表单、报表设计器</td><td>四款可嵌入的设计器</td><td><a href="https://docs.xihanfun.com" target="_blank" rel="noreferrer">组织门户</a></td></tr><tr><td>framework-spec</td><td>XiHan Spec：RFC、术语表、一致性向量与黑盒运行器</td><td><a href="https://github.com/XiHanFun/framework-spec" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td>framework-sdk-go</td><td>Go SDK，用于编写进程外插件与远程 Provider</td><td><a href="https://github.com/XiHanFun/framework-sdk-go" target="_blank" rel="noreferrer">GitHub</a></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/changelog">更新日志</a>：各版本的使用者可感知变更</li><li><a href="/appendix/milestones">发展大事记</a>：项目是怎么走到今天的</li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};